// Colour maps: 256 sRGB samples each (rrggbb, at i / 255), generated once by
// tools/colormap_tables.ts (d3's colour scheme data; single-hue maps dark to light; matplotlib's
// cyclic twilight; an HSL hue wheel).
// Provenance and licences (d3-scale-chromatic ISC, ColorBrewer Apache-2.0, BIDS CC0, Google Turbo
// Apache-2.0, matplotlib licence, ...): LICENSES/README.md at the repository root.

const TABLES: Record<string, string> = {
  Blues: "",
  Greens: "",
  Greys: "",
  Oranges: "",
  Purples: "",
  Reds: "",
  Turbo: "",
  Viridis: "",
  Inferno: "",
  Magma: "",
  Plasma: "",
  Cividis: "",
  Warm: "",
  Cool: "",
  Cubehelix: "",
  BuGn: "",
  BuPu: "",
  GnBu: "",
  OrRd: "",
  PuBuGn: "",
  PuBu: "",
  PuRd: "",
  RdPu: "",
  YlGnBu: "",
  YlGn: "",
  YlOrBr: "",
  YlOrRd: "",
  Twilight: "",
  Rainbow: "",
  Sinebow: "",
  HSL: "",
  BrBG: "",
  PRGn: "",
  PiYG: "",
  PuOr: "",
  RdBu: "",
  RdGy: "",
  RdYlBu: "",
  RdYlGn: "",
  Spectral: "",
};

export const COLORMAP_NAMES = Object.keys(TABLES);

/** The map's name as listed, matched case-insensitively (undefined if unknown). */
export function colormapName(name: string): string | undefined {
  return COLORMAP_NAMES.find((n) => n.toLowerCase() === name.toLowerCase());
}

const sample = (hex: string, i: number, c: number) => parseInt(hex.slice(i * 6 + c * 2, i * 6 + c * 2 + 2), 16);

/** 256 RGBA8 samples (sRGB), as an 8-bit colour map texture holds them. */
export function colormapLut(name: string, invert = false): Uint8Array {
  const hex = TABLES[colormapName(name) ?? "Viridis"];
  const out = new Uint8Array(256 * 4);
  for (let i = 0; i < 256; i += 1) {
    const k = invert ? 255 - i : i;
    out.set([sample(hex, k, 0), sample(hex, k, 1), sample(hex, k, 2), 255], i * 4);
  }
  return out;
}

/** sRGB (0-255) at t in [0, 1], linear between samples. */
export function colormapRgb(name: string, t: number, invert = false): [number, number, number] {
  const hex = TABLES[colormapName(name) ?? "Viridis"];
  const x = Math.min(Math.max(invert ? 1 - t : t, 0), 1) * 255;
  const i = Math.min(Math.floor(x), 254), f = x - i;
  return [0, 1, 2].map((c) => sample(hex, i, c) * (1 - f) + sample(hex, i + 1, c) * f) as [number, number, number];
}

/** sRGB (0-1) to linear RGB, as WebGPU shaders light and blend colours. */
export function srgbToLinear(c: number): number {
  return c < 0.04045 ? c * 0.0773993808 : Math.pow(c * 0.9478672986 + 0.0521327014, 2.4);
}

/** The 256 samples in linear RGB (`256 × 3`), as the surface and 3D curve shaders take them. */
export function getLinearColorLut(name: string, invert = false): Float32Array {
  const bytes = colormapLut(name, invert);
  const lut = new Float32Array(256 * 3);
  for (let i = 0; i < 256; i += 1) {
    lut.set([0, 1, 2].map((c) => srgbToLinear(bytes[i * 4 + c] / 255)), i * 3);
  }
  return lut;
}
